import heapq

def total_cost_to_hire_k_workers(costs, k, candidates):
    n = len(costs)
    left, right = 0, n - 1
    left_heap, right_heap = [], []

    while len(left_heap) < candidates and left <= right:
        heapq.heappush(left_heap, (costs[left], left))
        left += 1

    while len(right_heap) < candidates and left <= right:
        heapq.heappush(right_heap, (costs[right], right))
        right -= 1

    total = 0
    for _ in range(k):
        if right_heap and (not left_heap or right_heap[0][0] < left_heap[0][0]):
            cost, _ = heapq.heappop(right_heap)
            total += cost
            if left <= right:
                heapq.heappush(right_heap, (costs[right], right))
                right -= 1
        elif left_heap:
            cost, _ = heapq.heappop(left_heap)
            total += cost
            if left <= right:
                heapq.heappush(left_heap, (costs[left], left))
                left += 1

    return total

